-- PT113-S4-Q7. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT113-S4-Q7$batch07$ AND q.stimulus=$batch07$Hazel: Faster and more accurate order processing would help our business. To increase profits, we should process orders electronically rather than manually, because customers’ orders will then go directly to all relevant parties.
Max: We would lose money if we started processing orders electronically. Most people prefer to interact with human beings when placing orders. If we switch to electronic order processing, our business will appear cold and inhuman, and we will attract fewer customers.$batch07$ AND q.prompt=$batch07$Hazel and Max disagree over whether$batch07$ AND q.correct_choice=$batch07$C$batch07$) THEN RAISE EXCEPTION 'Question changed: PT113-S4-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT113-S4-Q7$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S4-Q7'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT113-S4-Q7$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Hazel's Position$batch07$, $batch07$Switching to electronic order processing would make orders faster and more accurate, so it would increase profits.$batch07$), (1, $batch07$Max's Position$batch07$, $batch07$Switching would lose money, because customers want a human and would go elsewhere.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Max never disputes that electronic processing is faster or more accurate. Max goes straight at the bottom line: Hazel says profits go up, Max says "we would lose money". That is a clean, head-on clash.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether switching to electronic processing would help the business financially.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT113-S4-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Hazel thinks electronic processing is faster and more accurate. Max never says it isn't. Max's objection is about how customers feel, not about speed.$batch07$), ($batch07$B$batch07$, $batch07$This is the most popular wrong answer, and it is close. Hazel says faster, more accurate processing would help. But Max never talks about speed or accuracy at all. Max talks about what *electronic* processing would do. B swaps the switch for its benefits, and Max has no stated view on the benefits.$batch07$), ($batch07$C$batch07$, $batch07$Hazel: switching will "increase profits". Max: "We would lose money if we started processing orders electronically." Both sides are stated outright.$batch07$), ($batch07$D$batch07$, $batch07$Neither speaker talks about an obligation to be as profitable as possible. They both want profit; the fight is over how to get it.$batch07$), ($batch07$E$batch07$, $batch07$Max thinks customers would find the business cold and inhuman. Hazel never addresses how customers would feel.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT113-S4-Q7$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
